BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(18);
SELECT ok(to_regprocedure('app_private.db03_principal_approve_input_source(uuid,bigint,uuid)') IS NOT NULL, 'typed private P36 source installed');
SELECT is((SELECT p.proowner::regrole::text FROM pg_proc p WHERE p.oid='app_private.db03_principal_approve_input_source(uuid,bigint,uuid)'::regprocedure), 'schoolos_schema_owner'::text, 'source owned by private schema owner');
SELECT ok(NOT (SELECT p.prosecdef FROM pg_proc p WHERE p.oid='app_private.db03_principal_approve_input_source(uuid,bigint,uuid)'::regprocedure), 'P36 source does not elevate invoker privileges');
SELECT ok((SELECT 'search_path=pg_catalog,pg_temp'=ANY(p.proconfig) FROM pg_proc p WHERE p.oid='app_private.db03_principal_approve_input_source(uuid,bigint,uuid)'::regprocedure), 'private source fixes safe search_path');
SELECT ok(NOT has_function_privilege('PUBLIC', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'PUBLIC has no executable approval source grant');
SELECT ok(NOT has_function_privilege('anon', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'anon has no executable approval source grant');
SELECT ok(NOT has_function_privilege('authenticated', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'authenticated has no executable approval source grant');
SELECT ok(NOT has_function_privilege('service_role', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'service_role has no executable approval source grant');
SELECT ok(NOT has_function_privilege('schoolos_workflow_executor', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'schoolos_workflow_executor has no executable approval source grant');
SELECT ok(NOT has_function_privilege('schoolos_file_login', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'schoolos_file_login has no executable approval source grant');
SELECT ok(NOT has_function_privilege('schoolos_platform_executor', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'schoolos_platform_executor has no executable approval source grant');
SELECT ok(NOT has_function_privilege('schoolos_evidence_writer', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'schoolos_evidence_writer has no executable approval source grant');
SELECT ok(NOT has_function_privilege('schoolos_authz_reader', 'app_private.db03_principal_approve_input_source(uuid,bigint,uuid)','EXECUTE'), 'schoolos_authz_reader has no executable approval source grant');
SELECT throws_ok($q$SELECT app_private.db03_principal_approve_input_source('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')$q$,'P0001','DB03 Principal APPROVE input invalid','invalid application version fails closed');
SELECT throws_ok($q$SELECT app_private.db03_principal_approve_input_source('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,NULL)$q$,'P0001','DB03 Principal APPROVE input invalid','missing Forward id fails closed');
SELECT is(app_private.db03_principal_approve_input_source(NULL,1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')::text,NULL::text,'missing application produces no approval');
SELECT is(app_private.db03_principal_approve_input_source('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')::text,NULL::text,'nonexistent application cannot forge approval');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid)') IS NULL,'P36 introduces no live public APPROVE command');
SELECT * FROM finish();
ROLLBACK;
